// SPDX-License-Identifier: Apache-2.0
//! Canonical tool-call assembly for one OpenAI choice (spec § 4.3, D9).
//!
//! Only choice 0 may carry tool calls, and only at array position 0 of its chunk, because LangChain
//! reads `choices[0]` of every chunk and ignores `choice.index`. A `type` that does not match the body's shape is a deviation, because
//! clients ignore `type` and run the body. Kind Other is only for a call with no body at all.
//!
//! The client SDKs disagree on everything outside this form. openai-python concatenates every
//! string except `index` and `type`, so a second `name` fragment turns `safe_` into `safe_rm`.
//! openai-node replaces the name, and LangChain merges by index value. Inside the canonical form
//! they all agree, so the decider sees exactly what every client will run.
//!
//! A tool-call entry with no `function` body (a custom call, or an entry with only an `index`) is
//! bodyless. LangChain raises at the first record that holds one (`rtc["function"].get`) and drops
//! that whole record. After such a record, a fragment of a call that existed before it would make
//! LangChain's snapshot of that call a strict prefix of the other clients' (spec § 2.1 M3). So that
//! fragment is a deviation (`fragment_after_bodyless_entry`), also in the bodyless record itself.
//! The rewrite removes a blocked call, so a later bodyless record can be the first one in the
//! output. So every bodyless record renews the boundary, not only the first one. A bodyless
//! fragment that continues a custom or Other call does not renew it and does not deviate: that
//! call's first record was bodyless already.
//! A fragment that adds nothing is a deviation too, on purpose: the rule does not read content.
//! Calls that start in or after the latest bodyless record are conforming.
//!
//! A present `type` key counts as the type fragment, `null` included (spec § 5.3, P-c): a second
//! one is `repeated_type`, and a first `"type": null` with a body is `type_shape_mismatch` at
//! completion. openai-python replaces `type` on every fragment, so a later `"type": null` turns a
//! function call's type into `None`, and its `new_tool.type == "function"` assert then raises with
//! a strict prefix of the arguments. A non-stream body keeps reading `null` as absent (D4).
//!
//! Every check runs on a small copy of the state ([`Check`]) before anything is changed, so a
//! deviation leaves the assembly exactly as it was.
//!
//! A function call's arguments are what clients parse, so at completion they must be one complete
//! JSON value ([`complete_arguments`]), as an Anthropic `tool_use` input must. LangChain
//! partial-parses a truncated string (`{"cmd":"ls` runs as `{"cmd":"ls"}`) and openai-node can
//! partial-parse it too, so the decider would see a string the client reads differently.

use serde_json::Value;

use crate::json::{check_numbers, parse_value_strict};
use crate::openai::classify::{Fragment, NameArgs};
use crate::protocol::{Deviation, MAX_IDENTIFIER_BYTES, raw_len};
use crate::types::{ToolCall, ToolCallKind};

#[derive(Clone, Copy, PartialEq, Eq)]
enum Shape {
    Function,
    Custom,
}

/// The class of a `type` value: all that the canonical checks read of it.
#[derive(Clone, Copy, PartialEq, Eq)]
enum TyClass {
    Function,
    Custom,
    Other,
}

/// What the canonical checks read of one call. It is small, so a whole record can be checked
/// against a copy before anything is changed: a deviation must never leave half-applied state, for
/// example a hold marked open that the interceptor never registered.
#[derive(Clone, Copy, Default)]
struct Shadow {
    id: bool,
    ty: Option<TyClass>,
    shape: Option<Shape>,
    name: bool,
}

/// The canonical-form state of one choice (spec § 4.3), without the strings.
#[derive(Clone, Default)]
pub(crate) struct Check {
    calls: Vec<Shadow>,
    /// `Some(has_name)` once a legacy `function_call` fragment arrived.
    legacy: Option<bool>,
    /// The number of calls that existed before the latest record with a new bodyless entry was
    /// applied. Each such record renews it, so it only grows.
    bodyless_at: Option<usize>,
}

fn once(slot: &mut bool, present: bool, why: &'static str) -> Result<(), Deviation> {
    if present {
        if *slot {
            return Err(Deviation(why));
        }
        *slot = true;
    }
    Ok(())
}

/// A tool-call id or name over `MAX_IDENTIFIER_BYTES` is a deviation (each arrives at most once).
fn long_check(id: Option<&str>, name: Option<&str>) -> Result<(), Deviation> {
    if id.is_some_and(|s| s.len() > MAX_IDENTIFIER_BYTES) || name.is_some_and(|s| s.len() > MAX_IDENTIFIER_BYTES) {
        return Err(Deviation("long_identifier"));
    }
    Ok(())
}

impl Check {
    fn apply(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
        let mixes = (legacy.is_some() && (!frags.is_empty() || !self.calls.is_empty())) || (!frags.is_empty() && self.legacy.is_some());
        if mixes {
            return Err(Deviation("legacy_and_tool_calls"));
        }
        if let Some(l) = legacy {
            long_check(None, l.name.as_deref())?;
            once(self.legacy.get_or_insert(false), l.name.is_some(), "repeated_name")?;
        }
        let before = self.calls.len();
        // A bodyless fragment of an existing call with no function body continues a call whose
        // first record was bodyless already. That record stays in the output before this one
        // when the call is allowed, and the rewrite removes both when it is blocked.
        let continues = |f: &Fragment| f.function.is_none() && self.calls.get(f.index as usize).is_some_and(|b| b.shape != Some(Shape::Function));
        // The rewrite can remove an earlier blocked bodyless call, so every bodyless record can be
        // the first one that LangChain reads: each one renews the boundary (it only grows).
        if frags.iter().any(|f| f.function.is_none() && !continues(f)) {
            self.bodyless_at = Some(before);
        }
        if let Some(n) = self.bodyless_at
            && frags.iter().any(|f| (f.index as usize) < n && !continues(f))
        {
            return Err(Deviation("fragment_after_bodyless_entry"));
        }
        for f in frags {
            let pos = f.index as usize;
            if pos == self.calls.len() {
                self.calls.push(Shadow::default());
            } else if pos > self.calls.len() {
                return Err(Deviation("index_gap"));
            }
            let b = &mut self.calls[pos];
            long_check(f.id.as_deref(), f.function.as_ref().or(f.custom.as_ref()).and_then(|na| na.name.as_deref()))?;
            once(&mut b.id, f.id.is_some(), "repeated_id")?;
            if f.ty_key {
                // The type names a bodyless Other call, so it is bounded like an id or a name.
                long_check(f.ty.as_deref(), None)?;
                if b.ty.is_some() {
                    return Err(Deviation("repeated_type"));
                }
                // A `null` type is a present key that names no known type, so it is Other.
                b.ty = Some(match f.ty.as_deref() {
                    Some("function") => TyClass::Function,
                    Some("custom") => TyClass::Custom,
                    _ => TyClass::Other,
                });
            }
            let (shape, na) = match (&f.function, &f.custom) {
                (Some(na), None) => (Some(Shape::Function), Some(na)),
                (None, Some(na)) => (Some(Shape::Custom), Some(na)),
                _ => (None, None),
            };
            if let Some(s) = shape {
                match b.shape {
                    None => b.shape = Some(s),
                    Some(prev) if prev != s => return Err(Deviation("shape_changed")),
                    Some(_) => {}
                }
            }
            if let Some(na) = na {
                once(&mut b.name, na.name.is_some(), "repeated_name")?;
            }
        }
        Ok(())
    }

    /// The kind of every call once the choice finishes, or the deviation that finishing is.
    pub(crate) fn finish(&self) -> Result<Vec<ToolCallKind>, Deviation> {
        if let Some(has_name) = self.legacy {
            if !has_name {
                return Err(Deviation("missing_name"));
            }
            return Ok(vec![ToolCallKind::LegacyFunctionCall]);
        }
        self.calls
            .iter()
            .map(|b| {
                // Clients ignore `type` and run the body, so any type other than the one the
                // body's shape expects is a deviation, never kind Other (spec I1).
                let kind = match (b.shape, b.ty) {
                    (Some(Shape::Function), Some(TyClass::Function) | None) => ToolCallKind::Function,
                    (Some(Shape::Custom), Some(TyClass::Custom) | None) => ToolCallKind::Custom,
                    (Some(_), Some(_)) => return Err(Deviation("type_shape_mismatch")),
                    (None, Some(TyClass::Function | TyClass::Custom)) => return Err(Deviation("missing_body")),
                    (None, _) => ToolCallKind::Other,
                };
                if kind != ToolCallKind::Other && !b.name {
                    return Err(Deviation("missing_name"));
                }
                Ok(kind)
            })
            .collect()
    }
}

#[derive(Default)]
struct CallBuild {
    id: Option<String>,
    ty: Option<String>,
    name: Option<String>,
    args: String,
    raws: Vec<Value>,
}

#[derive(Default)]
pub(crate) struct ChoiceAssembly {
    calls: Vec<CallBuild>,
    legacy: Option<CallBuild>,
    check: Check,
    /// The bytes held in arguments and raw entries.
    retained: usize,
    /// An observed choice outgrew the cap: it keeps nothing and is never decided (§ 5.3, D13).
    overflowed: bool,
}

/// Kind Other carries its raw entries. serde_json rounds an integer beyond u64/i64, so the decider
/// would read a different number than a client that keeps the exact one (I1, as for bodies).
fn check_raws<'a>(raws: impl IntoIterator<Item = &'a Value>) -> Result<(), Deviation> {
    raws.into_iter().try_for_each(check_numbers).map_err(|_| Deviation("lossy_number"))
}

/// Tool data is allowed only in choice 0, and only at array position 0 of its chunk (spec § 4.3).
/// LangChain reads `choices[0]` of every chunk and ignores `choice.index`. So a call split across
/// choices 0 and 1 would be merged by it but assembled separately here (`multi_choice_tool_calls`),
/// and a choice-0 fragment behind another choice's entry would never reach it
/// (`choice_position`). Text in other choices and positions stays allowed.
pub(crate) fn check_tool_choice(choice: u32, position: usize, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
    if frags.is_empty() && legacy.is_none() {
        return Ok(());
    }
    if choice != 0 {
        return Err(Deviation("multi_choice_tool_calls"));
    }
    if position != 0 {
        return Err(Deviation("choice_position"));
    }
    Ok(())
}

/// The arguments the decider sees for a completed call of `kind`. A function or legacy call's
/// arguments must be one complete JSON value; an empty string is presented as `{}`, as an empty
/// Anthropic input is. A custom tool's input is free-form text and is not checked; kind Other
/// carries its raw entry.
pub(crate) fn complete_arguments(kind: ToolCallKind, args: String) -> Result<String, Deviation> {
    match kind {
        ToolCallKind::Function | ToolCallKind::LegacyFunctionCall => {
            if args.is_empty() {
                Ok("{}".to_owned())
            } else if parse_value_strict(args.as_bytes()).is_ok() {
                Ok(args)
            } else {
                Err(Deviation("incomplete_arguments"))
            }
        }
        _ => Ok(args),
    }
}

impl ChoiceAssembly {
    /// The canonical-form state after these fragments, or the deviation they are. Changes nothing.
    pub(crate) fn check(&self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<Check, Deviation> {
        let mut c = self.check.clone();
        c.apply(frags, legacy)?;
        Ok(c)
    }

    /// The current canonical-form state.
    pub(crate) fn state(&self) -> &Check {
        &self.check
    }

    /// Apply fragments that [`ChoiceAssembly::check`] accepted, with `after` its result. Cannot fail.
    pub(crate) fn commit(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>, after: Check) {
        if let Some(l) = legacy {
            let b = self.legacy.get_or_insert_with(CallBuild::default);
            if let Some(n) = &l.name {
                b.name = Some(n.clone());
            }
            if let Some(a) = &l.args {
                b.args.push_str(a);
                self.retained += a.len();
            }
        }
        for f in frags {
            let pos = f.index as usize;
            while self.calls.len() <= pos {
                self.calls.push(CallBuild::default());
            }
            let b = &mut self.calls[pos];
            if let Some(id) = &f.id {
                b.id = Some(id.clone());
            }
            if let Some(t) = &f.ty {
                b.ty = Some(t.clone());
            }
            if let Some(na) = f.function.as_ref().or(f.custom.as_ref()) {
                if let Some(n) = &na.name {
                    b.name = Some(n.clone());
                }
                if let Some(a) = &na.args {
                    b.args.push_str(a);
                    self.retained += a.len();
                }
            }
            // Only kind Other reads its raw entries, and only a call with no body is Other. A call
            // whose body arrived drops them, so its arguments are not held twice.
            if after.calls.get(pos).is_some_and(|s| s.shape.is_none()) {
                self.retained += raw_len(&f.raw);
                b.raws.push(f.raw.clone());
            } else if !b.raws.is_empty() {
                self.retained -= std::mem::take(&mut b.raws).iter().map(raw_len).sum::<usize>();
            }
        }
        self.check = after;
    }

    /// Observe mode (§ 5.3): apply what fits, and stop retaining once the choice holds more than
    /// `cap` bytes. The choice is then never decided, as a pass-through call is not.
    pub(crate) fn observe(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>, cap: usize) {
        if self.overflowed {
            return;
        }
        let _ = self.apply(frags, legacy);
        if self.retained > cap {
            self.overflowed = true;
            self.drop_buffers();
        }
    }

    pub(crate) fn overflowed(&self) -> bool {
        self.overflowed
    }

    /// Drop every argument and raw buffer, keeping the names. Used once the choice finished.
    pub(crate) fn drop_buffers(&mut self) {
        for b in self.calls.iter_mut().chain(&mut self.legacy) {
            b.args = String::new();
            b.raws = Vec::new();
        }
        self.retained = 0;
    }

    /// Check, then commit. On a deviation nothing is changed.
    pub(crate) fn apply(&mut self, frags: &[Fragment], legacy: Option<&NameArgs>) -> Result<(), Deviation> {
        let after = self.check(frags, legacy)?;
        self.commit(frags, legacy, after);
        Ok(())
    }

    /// Phase-1 form of [`ChoiceAssembly::finish`]: whether finishing would succeed once `frags` and
    /// `legacy` (already accepted by [`ChoiceAssembly::check`], with result `after`) are applied.
    /// Changes nothing.
    pub(crate) fn check_finish(&self, frags: &[Fragment], legacy: Option<&NameArgs>, after: &Check) -> Result<(), Deviation> {
        let kinds = after.finish()?;
        let pending = |own: Option<&CallBuild>, more: &mut dyn Iterator<Item = &str>| -> String {
            let mut a = own.map(|b| b.args.clone()).unwrap_or_default();
            more.for_each(|x| a.push_str(x));
            a
        };
        if after.legacy.is_some() {
            let args = pending(self.legacy.as_ref(), &mut legacy.and_then(|l| l.args.as_deref()).into_iter());
            return complete_arguments(ToolCallKind::LegacyFunctionCall, args).map(drop);
        }
        for (i, kind) in kinds.into_iter().enumerate() {
            let mine = frags.iter().filter(|f| f.index as usize == i);
            if kind == ToolCallKind::Other {
                check_raws(self.calls.get(i).into_iter().flat_map(|b| &b.raws).chain(mine.map(|f| &f.raw)))?;
                continue;
            }
            let mut more = mine.filter_map(|f| f.function.as_ref().or(f.custom.as_ref()).and_then(|na| na.args.as_deref()));
            complete_arguments(kind, pending(self.calls.get(i), &mut more))?;
        }
        Ok(())
    }

    /// The completed calls. Moves the buffers out, so a finished choice keeps no arguments.
    pub(crate) fn finish(&mut self, choice: u32) -> Result<Vec<ToolCall>, Deviation> {
        let kinds = self.check.finish()?;
        self.retained = 0;
        if let Some(b) = &mut self.legacy {
            return Ok(vec![ToolCall {
                choice,
                position: 0,
                id: None,
                name: b.name.clone().unwrap_or_default(),
                namespace: None,
                kind: ToolCallKind::LegacyFunctionCall,
                arguments: complete_arguments(ToolCallKind::LegacyFunctionCall, std::mem::take(&mut b.args))?,
            }]);
        }
        let mut out = Vec::with_capacity(self.calls.len());
        for ((i, b), kind) in self.calls.iter_mut().enumerate().zip(kinds) {
            let (name, arguments) = if kind == ToolCallKind::Other {
                let name = b.name.clone().or_else(|| b.ty.clone()).unwrap_or_else(|| "unknown".to_owned());
                let raws = std::mem::take(&mut b.raws);
                check_raws(&raws)?;
                (name, serde_json::to_string(&raws).expect("a Value array always serializes"))
            } else {
                b.raws = Vec::new();
                (b.name.clone().unwrap_or_default(), complete_arguments(kind, std::mem::take(&mut b.args))?)
            };
            let position = u32::try_from(i).expect("at most 128 calls per choice");
            out.push(ToolCall {
                choice,
                position,
                id: b.id.clone(),
                name,
                namespace: None,
                kind,
                arguments,
            });
        }
        Ok(out)
    }

    /// The argument and raw-entry bytes held, measured exactly. Tests only.
    #[cfg(test)]
    pub(crate) fn retained(&self) -> usize {
        self.calls.iter().chain(&self.legacy).map(|b| b.args.len() + crate::protocol::raws_len(&b.raws)).sum()
    }

