        assert_eq!(deviation(evs), "arguments_mismatch");
        let mut evs = base();
        evs[6]["item"]["arguments"] = json!("{\"a\":2}");
        evs[7]["response"]["output"][0]["arguments"] = json!("{\"a\":2}");
        assert_eq!(deviation(evs), "arguments_mismatch");
        // A delta after the `.done` event, and a second `.done` event.
