        let got: Vec<(u32, Option<String>, String, ToolCallKind, String)> = a.hold_calls().into_iter().map(|c| (c.position, c.id, c.name, c.kind, c.arguments)).collect();
        let s = |x: &str| x.to_owned();
        assert_eq!(
